package com.bank.scaling.service;

import com.bank.scaling.model.DbMetrics;
import com.bank.scaling.model.ScalingStep;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

@Service
public class ScalingAdvisor {
    private static final Logger log = LoggerFactory.getLogger(ScalingAdvisor.class);

    // Recommend the NEXT cheapest step. Never jumps to SHARD until all else is exhausted.
    public ScalingStep recommend(DbMetrics m) {
        if (m.hasUnindexedHotQueries) {
            log.info("Fix queries/indexes first — cheapest and often the whole fix.");
            return ScalingStep.OPTIMIZE_QUERIES_INDEXES;
        }
        if (m.currentCpuCores < m.maxCpuCores) {
            log.info("Scale up vertically — no code change, big headroom.");
            return ScalingStep.SCALE_UP_VERTICALLY;
        }
        if (!m.replicasInPlace && m.readWriteRatio >= 5) {
            log.info("Read-heavy workload — add read replicas to offload the primary.");
            return ScalingStep.ADD_READ_REPLICAS;
        }
        if (!m.cacheInPlace) {
            log.info("Add a cache for hot read-mostly data — microsecond reads.");
            return ScalingStep.ADD_CACHE;
        }
        if (!m.cqrsInPlace) {
            log.info("Apply CQRS — scale read and write models independently.");
            return ScalingStep.APPLY_CQRS;
        }
        if (m.writeThroughputExceedsSingleNode) {
            log.warn("All cheaper layers exhausted AND writes exceed one node — shard now.");
            return ScalingStep.SHARD;
        }
        log.info("No sharding needed — earlier layers are sufficient.");
        return ScalingStep.APPLY_CQRS;  // stay put; sharding not justified
    }
}
